def write_split(total, parts, path):
    if parts < 1:
        raise ValueError("parts must be >= 1")
    q, r = divmod(total, parts)
    arr = [q + 1] * r + [q] * (parts - r)
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        for x in arr:
            fh.write(f"{x}\n")

